function.arguments:
{"script":"() => {
  // Look for hero headlines, slogans, subheads
  const hero = document.querySelector('section h1, section h2');
  const headline = document.querySelector('.hero-headline, [class*="headline"]');
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, [class*="subhead"], [class*="eyebrow"]')).slice(0, 30);
  return {
    h1: document.querySelector('h1')?.innerText,
    h2s: Array.from(document.querySelectorAll('h2')).slice(0, 10).map(h => h.innerText.trim()),
    headlines: headings.map(h => h.innerText.trim()).filter(t => t.length > 0 && t.length < 200),
    title: document.title,
    metaDesc: document.querySelector('meta[name="description"]')?.content,
    ogDesc: document.querySelector('meta[property="og:description"]')?.content,
  };
}"}

